def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

print(factorial(5))

def describe(**info):
    for key, value in info.items():
        print(f'{key}: {value}')

describe(name='Bob', age=30)

def clamp(value, low, high):
    return max(low, min(value, high))

print(clamp(15, 0, 10))

def count_vowels(text):
    vowels = 'aeiouAEIOU'
    count = 0
    for char in text:
        if char in vowels:
            count += 1
    return count

print(count_vowels('Hello World'))

def palindrome(word):
    return word == word[::-1]

print(palindrome('racecar'))

